package com.citacloud.app.views; import com.citacloud.app.models.Servicio; import com.citacloud.app.security.*; import com.citacloud.app.services.ServicioService; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.checkbox.Checkbox; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.BigDecimalField; import com.vaadin.flow.component.textfield.TextArea; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="servicios",layout=MainLayout.class) @PageTitle("Servicios | CitaCloud") @PermitAll public class ServiciosView extends VerticalLayout {private final ServicioService service;private final UUID empresa;private final Grid<Servicio> grid=new Grid<>(Servicio.class,false);public ServiciosView(ServicioService s){service=s;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);add(new HorizontalLayout(new H2("Servicios médicos"),new Button("Nuevo servicio",e->form(null))),new Paragraph("Catálogo de servicios disponible para facturación."));grid.addColumn(Servicio::getCodigo).setHeader("CÓDIGO");grid.addColumn(Servicio::getNombre).setHeader("NOMBRE");grid.addColumn(Servicio::getPrecio).setHeader("PRECIO");grid.addColumn(x->Boolean.TRUE.equals(x.getActivo())?"Activo":"Inactivo").setHeader("ESTADO");grid.addComponentColumn(x->new Button("Editar",e->form(x))).setHeader("ACCIONES");grid.setWidthFull();add(grid);cargar();}private void cargar(){grid.setItems(empresa==null?List.of():service.listar(empresa));}private void form(Servicio actual){if(empresa==null)return;Dialog d=new Dialog();TextField codigo=new TextField("Código",actual==null?"":actual.getCodigo());TextField nombre=new TextField("Nombre",actual==null?"":actual.getNombre());TextArea descripcion=new TextArea("Descripción",actual==null?"":actual.getDescripcion());BigDecimalField precio=new BigDecimalField("Precio");if(actual!=null)precio.setValue(actual.getPrecio());Checkbox activo=new Checkbox("Activo",actual==null||Boolean.TRUE.equals(actual.getActivo()));Button guardar=new Button("Guardar",e->{try{service.guardar(empresa,actual==null?null:actual.getId(),codigo.getValue(),nombre.getValue(),descripcion.getValue(),precio.getValue(),activo.getValue());d.close();cargar();Notification.show("Servicio guardado correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new VerticalLayout(codigo,nombre,descripcion,precio,activo,guardar));d.open();}}
